-- generated by Art/Studio/Regions/kit.py from restore_region.lua.tmpl (2026-10-24): do not edit by hand.
-- Region Testbed: undoes finish.lua's real run, in Studio Edit, without destroying anything. It uses the newest
-- ServerStorage.RenseiBackups["Pre-Region_<Region>_<date>"] that finish.lua made (set DATE below to pick another).
-- It refuses, changing nothing, if: there is no such backup; workspace.World.Map is missing; the import that backup
-- made (World.Map.Testbed, found through the backup's MapChildRef) is not in World.Map; or a backed-up child's
-- name is already taken in World.Map by something else. Then, inside a pcall that undoes it all on an error:
--   moves World.Map.Testbed, with any edits made since the import, into
--   RenseiBackups["Post-Region_<Region>_<run date>"] (a _2, _3 ... suffix if that exists), its CollectionService
--   tags stripped into RegionKitTags (run import/unstrip.lua on a piece you drag back out); moves the kit's
--   MaterialVariants there too; moves the backed-up Map children back into World.Map and re-adds their tags; puts
--   back the MaterialVariants the import replaced; pastes back the terrain under the water boxes; then removes the
--   emptied Pre-Region backup. Kept World.Map children are never touched.
-- The swap is recorded with ChangeHistoryService so Studio's Undo can take it back, when Studio allows a recording
-- here (through the Studio bridge a recording is already open, and the bridge's own waypoint covers the run).
-- It does NOT bring back anything retired by hand before or after the import (in Ye: the old NorthRoad passage and its
-- RoadStart arrival, the HubRoad strip, the north buffer stop): put those back from their own backups.
local HS = game:GetService("HttpService")
local SS = game:GetService("ServerStorage")
local MS = game:GetService("MaterialService")
local CS = game:GetService("CollectionService")

local REGION, MAPCHILD = "Testbed", "Testbed"
local DATE = nil -- e.g. "2026-10-24" to restore that day's backup; nil = the newest

local Backups = SS:FindFirstChild("RenseiBackups")
local Prefix = "Pre-Region_" .. REGION .. "_"
local B
for _, C in ipairs(Backups and Backups:GetChildren() or {}) do
	if C.Name:sub(1, #Prefix) == Prefix and C:GetAttribute("RegionKitRegion") == REGION
		and (DATE == nil or C.Name == Prefix .. DATE) and (B == nil or C.Name > B.Name) then
		B = C
	end
end
if not B then return "restore refused: no RenseiBackups." .. Prefix .. (DATE or "<date>") .. " made by finish.lua; nothing changed" end
local World = workspace:FindFirstChild("World")
local Map = World and World:FindFirstChild("Map")
if not Map then return "restore refused: no workspace.World.Map; nothing changed" end
local Ref = B:FindFirstChild("MapChildRef")
local Dest = Ref and Ref.Value
if not (Dest and Dest.Parent == Map) then
	return "restore refused: the World.Map." .. (B:GetAttribute("MapChild") or MAPCHILD) .. " made with backup " .. B.Name
		.. " is not in World.Map; nothing changed"
end
local BMap = B:FindFirstChild("Map")
local Clash = {}
for _, C in ipairs(BMap and BMap:GetChildren() or {}) do
	for _, Live in ipairs(Map:GetChildren()) do
		if Live ~= Dest and Live.Name == C.Name then table.insert(Clash, C.Name) break end
	end
end
if #Clash > 0 then
	return "restore refused: World.Map already has " .. table.concat(Clash, ", ") .. " (rename or move it first); nothing changed"
end
local PostName = "Post-Region_" .. REGION .. "_" .. os.date("%Y-%m-%d")
if Backups:FindFirstChild(PostName) then
	local N = 2
	while Backups:FindFirstChild(PostName .. "_" .. N) do N += 1 end
	PostName = PostName .. "_" .. N
end

local Journal, Stripped, Unstripped, Undo, Back = {}, {}, {}, {}, {}
local P
local function Move(I, To)
	table.insert(Journal, {I, I.Parent})
	I.Parent = To
end
local function StripOne(D)
	local T = CS:GetTags(D)
	if #T > 0 then
		D:SetAttribute("RegionKitTags", HS:JSONEncode(T))
		for _, Tag in ipairs(T) do CS:RemoveTag(D, Tag) end
		table.insert(Stripped, D)
	end
end
local function UnstripOne(D)
	local J = D:GetAttribute("RegionKitTags")
	if J then
		for _, Tag in ipairs(HS:JSONDecode(J)) do CS:AddTag(D, Tag) end
		D:SetAttribute("RegionKitTags", nil)
		table.insert(Unstripped, {D, J})
	end
end
local function Each(Root, F)
	F(Root)
	for _, D in ipairs(Root:GetDescendants()) do F(D) end
end

local CHS = game:GetService("ChangeHistoryService")
local ROk, Rec = pcall(CHS.TryBeginRecording, CHS, "Region restore " .. REGION, "restore.lua: " .. REGION .. " back to its backup")
local UndoText = (ROk and Rec) and "undo: recorded as one Studio Undo step" or ("undo: the caller's recording (" .. (ROk and "a recording is already open" or tostring(Rec)) .. ")")
local function EndRecording()
	if ROk and Rec then pcall(CHS.FinishRecording, CHS, Rec, Enum.FinishRecordingOperation.Commit) end
end
local Ok, Err = pcall(function()
	P = Instance.new("Folder")
	P.Name = PostName
	P:SetAttribute("RegionKitRegion", REGION)
	P:SetAttribute("MapChild", MAPCHILD)
	P:SetAttribute("FromBackup", B.Name)
	P.Parent = Backups
	Each(Dest, StripOne)
	Move(Dest, P)
	local VF = B:FindFirstChild("VariantsAdded")
	if VF then
		local PV = Instance.new("Folder")
		PV.Name = "MaterialVariants"
		PV.Parent = P
		for _, R in ipairs(VF:GetChildren()) do
			local V = R:IsA("ObjectValue") and R.Value
			if V and V.Parent == MS then
				Each(V, StripOne)
				Move(V, PV)
			end
		end
	end
	for _, C in ipairs(BMap and BMap:GetChildren() or {}) do
		Move(C, Map)
		Each(C, UnstripOne)
		table.insert(Back, C.Name)
	end
	local BVar = B:FindFirstChild("MaterialVariants")
	for _, Old in ipairs(BVar and BVar:GetChildren() or {}) do
		Move(Old, MS)
		Each(Old, UnstripOne)
	end
	local WF = B:FindFirstChild("Water")
	local Snaps = WF and WF:GetChildren() or {}
	table.sort(Snaps, function(A, Z) return (tonumber(A.Name:sub(4)) or 0) > (tonumber(Z.Name:sub(4)) or 0) end) -- reverse fill order
	for _, Snap in ipairs(Snaps) do
		local C = Snap:GetAttribute("Corner")
		local Corner = Vector3int16.new(C.X, C.Y, C.Z)
		local Size = Snap.SizeInCells
		local Now = workspace.Terrain:CopyRegion(Region3int16.new(Corner,
			Vector3int16.new(C.X + Size.X - 1, C.Y + Size.Y - 1, C.Z + Size.Z - 1)))
		table.insert(Undo, {Now, Corner})
		workspace.Terrain:PasteRegion(Snap, Corner, true)
	end
end)
if not Ok then
	local UOk, RErr = pcall(function()
		for I = #Undo, 1, -1 do workspace.Terrain:PasteRegion(Undo[I][1], Undo[I][2], true) end
		for I = #Journal, 1, -1 do Journal[I][1].Parent = Journal[I][2] end
		for _, U in ipairs(Unstripped) do
			for _, Tag in ipairs(HS:JSONDecode(U[2])) do CS:RemoveTag(U[1], Tag) end
			U[1]:SetAttribute("RegionKitTags", U[2])
		end
		for _, D in ipairs(Stripped) do
			for _, Tag in ipairs(HS:JSONDecode(D:GetAttribute("RegionKitTags"))) do CS:AddTag(D, Tag) end
			D:SetAttribute("RegionKitTags", nil)
		end
		if P then P:Destroy() end
	end)
	EndRecording()
	if not UOk then
		return "restore FAILED (" .. tostring(Err) .. ") AND ITS UNDO FAILED (" .. tostring(RErr) .. "): finish by hand from RenseiBackups."
			.. B.Name .. " and " .. PostName
	end
	return "restore FAILED and was undone: " .. tostring(Err) .. "; nothing changed"
end
local BName = B.Name
B:Destroy() -- emptied: its Map children, variants and terrain snapshots have been used
EndRecording()
return ("restore: World.Map.%s (with any edits) moved to RenseiBackups.%s, %d tagged instances stripped (run unstrip.lua on a piece you drag back); back in World.Map: %s; %d tagged instances re-tagged; %d terrain snapshots pasted; backup %s removed; %s; pieces retired by hand are not put back by this script")
	:format(MAPCHILD, PostName, #Stripped, #Back > 0 and table.concat(Back, ", ") or "nothing", #Unstripped, #Undo, BName, UndoText)
